#!/usr/bin/env bash
set -euo pipefail
# Ensure verification compiles with the same settings as deployment.
export FOUNDRY_PROFILE="${FOUNDRY_PROFILE:-default}"
ETHERSCAN_API_KEY="${ETHERSCAN_API_KEY:-${ETHERSCAN_V2_API_KEY:-}}"
if [ -z "$ETHERSCAN_API_KEY" ]; then echo "set ETHERSCAN_API_KEY (or ETHERSCAN_V2_API_KEY)"; exit 1; fi
CHAIN_ID=8453
VERIFIER_URL="${VERIFIER_URL:-https://api.etherscan.io/v2/api?chainid=8453}"

# Foundry uses --chain (docs) but some older builds accepted --chain-id.
CHAIN_FLAG="--chain"
if forge verify-contract --help 2>/dev/null | grep -q -- "--chain-id"; then CHAIN_FLAG="--chain-id"; fi

PROFILE_FLAG=""
if forge verify-contract --help 2>/dev/null | grep -q -- "--compilation-profile"; then PROFILE_FLAG="--compilation-profile default"; fi

forge verify-contract 0xd480116D2366FCDbf2e31eAbd2480B42e271CFC5 src/adapters/chainlink/ChainlinkV2PlusWrapperAdapter.sol:ChainlinkV2PlusWrapperAdapter $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000b0407dbe851f8318bd31404a49e658143c982f23000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x4042a63885FE60D496E84Eba9aeef1885A82fC35 src/core/VRFHub.sol:VRFHub $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000d480116d2366fcdbf2e31eabd2480b42e271cfc5000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x17DF0fA1F7c26fBfa3773c63F70E5075ab6B21Bf src/core/PoolRegistry.sol:PoolRegistry $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0x7DDF1BddC313459C560e24CA8758A2Aa7c772974 src/core/SettlementRouter.sol:SettlementRouter $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x00000000000000000000000017df0fa1f7c26fbfa3773c63f70e5075ab6b21bf
forge verify-contract 0x52Ceb25Fc01a94AC4b7D6B52055040ECa9f9dFb2 src/engines/referral/ReferralRegistry.sol:ReferralRegistry $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 0x000000000000000000000000c8ec9920d573893e888db5d30b2b3b3824b1b684
forge verify-contract 0xea3c912F0A6CfB441e9791BCDb42B93F1434FDd9 src/engines/referral/DefaultReferralEngine.sol:DefaultReferralEngine $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x3f57E7d73d17Bbe5b77dCb1A7bD9a0c190EB77F3 src/core/GameHub.sol:GameHub $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0x597266Ba243455f1A9145bA0Cdc0408AaE532c77 src/core/Bank.sol:Bank $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0xf63c7c3304469F524Ad3433DacE31401E8472955 src/core/Bank.sol:Bank $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY" --constructor-args 
forge verify-contract 0xde044CC4DFCe570c5519C81f175f88AB8D8E8Ff4 src/modules/dice/DiceModule.sol:DiceModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xD6D864269B1E65b72e27351AFe310bD4A8a640d9 src/modules/cointoss/CoinTossModule.sol:CoinTossModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x3c09F74BbbB05322FA14477d89059cd2Be562D00 src/modules/roulette/RouletteModule.sol:RouletteModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xD279167a1D431889Bd0B343Ab389F75094BB50ce src/modules/keno/KenoModule.sol:KenoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x88DA1931A112Ef11DD0C1DF4Ade7581dac7Bed56 src/modules/plinko/PlinkoModule.sol:PlinkoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0xD9eBA528EeEF3E3698245E348Ce5FA7d16Da7401 src/modules/sicbo/SicBoModule.sol:SicBoModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x25f239332BBd3D2b3C627307d448797424389C86 src/modules/slots/SlotsModule.sol:SlotsModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
forge verify-contract 0x24b9AbBAEEE51edF39942E0a2FA42B925c461B5d src/modules/baccarat/BaccaratModule.sol:BaccaratModule $CHAIN_FLAG $CHAIN_ID $PROFILE_FLAG --watch --verifier etherscan --verifier-url "$VERIFIER_URL" --etherscan-api-key "$ETHERSCAN_API_KEY"
